import { useState } from 'react';

export default function MediaPage() {

  const MEDIA_ITEMS = [
    {
      id: 1,
      tag: "Press",
      date: "2024-03-15",
      title: "WLB India in the News",
      description: "Coverage across major Indian publications featuring our butterfly conservation work.",
      source: "Various",
      links: [
        { label: "Anandabazar Patrika — Nilpuja fasting article", url: "https://web.archive.org/web/20260411064234/https://www.anandabazar.com/horoscope/why-bengali-mother-do-fasting-in-the-auspicious-day-of-nilpuja-dgtl/cid/1679760" },
        { label: "Times of India — Butterfly corridor", url: "https://timesofindia.indiatimes.com" },
        { label: "The Hindu — Conservation report", url: "https://thehindu.com" },
      ],
    },
    {
      id: 2,
      tag: "Research",
      date: "2024-01-10",
      title: "Papilionidae of Northeast India",
      description: "Peer-reviewed paper on swallowtail distribution patterns across Arunachal Pradesh.",
      source: "Journal of Lepidopterology",
      url: "https://example.com/paper",
    },
    {
      id: 3,
      tag: "Research",
      date: "2023-11-05",
      title: "Citizen Science & Butterfly Mapping",
      description: "How our 4,200+ volunteer network is reshaping biodiversity data collection in India.",
      source: "Current Science India",
      links: [
        { label: "Full paper — Current Science (2023)", url: "https://currentscience.ac.in" },
        { label: "Supplementary data & methodology", url: "https://currentscience.ac.in" },
        { label: "Press release — DST India", url: "https://dst.gov.in" },
      ],
    },
    {
      id: 4,
      tag: "Field Report",
      date: "2024-02-20",
      title: "Winter Survey — Western Ghats 2024",
      description: "Field notes and photographic records from our 3-week expedition across Kerala and Karnataka.",
      source: "WLB India Field Team",
      url: "https://wlbindia.org/reports/ghats-2024",
    },
    {
      id: 5,
      tag: "Press",
      date: "2023-09-01",
      title: "UN Young Champion Feature — Ravi Sundar",
      description: "International coverage following our community science lead's UN recognition.",
      source: "UN Environment Programme",
      links: [
        { label: "UN Environment Programme — official profile", url: "https://unep.org" },
        { label: "Scroll.in — interview with Ravi Sundar", url: "https://scroll.in" },
        { label: "Mongabay India — conservation spotlight", url: "https://india.mongabay.com" },
        { label: "Deccan Herald — full feature story", url: "https://deccanherald.com" },
      ],
    },
    {
      id: 6,
      tag: "Field Report",
      date: "2023-07-14",
      title: "Monsoon Migration Tracking — 2023",
      description: "GPS-tagged sightings during the Southwest monsoon migration season across 12 states.",
      source: "WLB India Research Division",
      url: "https://wlbindia.org/reports/monsoon-2023",
    },
  ];

  const TAG_COLORS = {
    "Press":        "t-green",
    "Research":     "t-blue",
    "Field Report": "t-orange",
  };

  const [activeUrl, setActiveUrl]     = useState(null);
  const [activeTitle, setActiveTitle] = useState("");
  const [filter, setFilter]           = useState("All");

  const allTags  = ["All", ...new Set(MEDIA_ITEMS.map(item => item.tag))];
  const filtered = filter === "All" ? MEDIA_ITEMS : MEDIA_ITEMS.filter(item => item.tag === filter);

  const openUrl = (url, title) => { setActiveUrl(url); setActiveTitle(title); };

  const totalLinks = filtered.reduce((acc, item) =>
    acc + (item.links?.length || (item.url ? 1 : 0)), 0
  );

  return (
    <div style={{ padding: "7rem 1.5rem 4rem", maxWidth: 1200, margin: "0 auto" }}>

      {/* ── Header ── */}
      <div style={{ marginBottom: "2.5rem" }}>
        <div className="sec-eye">Press · Research · Field Reports</div>
        <h1 className="sec-h">Media &amp; <em>Publications</em></h1>
        <p className="sec-sub" style={{ marginTop: ".5rem" }}>
          Coverage, research papers, and field reports from our work.
        </p>
      </div>

      {/* ── Tag filter bar ── */}
      <div style={{ display: "flex", gap: ".5rem", flexWrap: "wrap", marginBottom: "2rem" }}>
        {allTags.map(tag => (
          <button
            key={tag}
            onClick={() => setFilter(tag)}
            style={{
              background: filter === tag ? "rgba(82,201,123,.14)" : "transparent",
              border: `1px solid ${filter === tag ? "rgba(82,201,123,.48)" : "var(--border)"}`,
              color: filter === tag ? "var(--green)" : "var(--text2)",
              padding: ".38rem 1.05rem",
              borderRadius: 50,
              fontFamily: "var(--fb)",
              fontSize: ".8rem",
              cursor: "pointer",
              transition: "all .2s",
            }}
          >
            {tag}
          </button>
        ))}
      </div>

      {/* ── Main layout ── */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: "center", padding: "4rem", color: "var(--text3)", fontFamily: "var(--ff)", fontSize: "1.1rem" }}>
          No items in this category yet.
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: "1.5rem", alignItems: "start" }}>

          {/* ── LEFT: single scrollable all-links card ── */}
          <div
            className="card"
            style={{ padding: 0, overflow: "hidden", position: "sticky", top: "5.5rem" }}
          >
            {/* Card header */}
            <div style={{ padding: "1rem 1.25rem", borderBottom: "1px solid var(--border)" }}>
              <div style={{ fontFamily: "var(--ff)", fontSize: "1rem", color: "var(--text)", marginBottom: ".2rem" }}>
                All Links
              </div>
              <div style={{ fontSize: ".72rem", color: "var(--text3)" }}>
                {totalLinks} articles &amp; reports
              </div>
            </div>

            {/* Scrollable list */}
            <div style={{ overflowY: "auto", maxHeight: "68vh" }}>
              {filtered.map((item) => {
                const links = item.links?.length
                  ? item.links
                  : item.url ? [{ label: item.title, url: item.url }] : [];
                if (!links.length) return null;
                return (
                  <div key={item.id}>
                    {/* Group label */}
                    <div style={{
                      padding: ".4rem 1.25rem",
                      fontSize: ".68rem",
                      color: "var(--text3)",
                      background: "var(--bg3)",
                      borderBottom: "1px solid var(--border)",
                      display: "flex",
                      alignItems: "center",
                      gap: ".5rem",
                    }}>
                      <span className={`tag ${TAG_COLORS[item.tag] || "t-blue"}`} style={{ fontSize: ".6rem" }}>
                        {item.tag}
                      </span>
                      <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                        {item.title}
                      </span>
                    </div>

                    {/* Links */}
                    {links.map((link, li) => (
                      <div
                        key={li}
                        onClick={() => openUrl(link.url, link.label)}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          gap: ".75rem",
                          padding: ".6rem 1.25rem",
                          cursor: "pointer",
                          borderBottom: "1px solid var(--border)",
                          transition: "background .15s",
                        }}
                        onMouseEnter={e => e.currentTarget.style.background = "var(--bg3)"}
                        onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                      >
                        <div style={{ display: "flex", alignItems: "center", gap: ".5rem", minWidth: 0 }}>
                          <span style={{ fontSize: "12px", flexShrink: 0 }}>🔗</span>
                          <span style={{
                            fontSize: ".79rem",
                            color: "var(--text2)",
                            overflow: "hidden",
                            textOverflow: "ellipsis",
                            whiteSpace: "nowrap",
                          }}>
                            {link.label}
                          </span>
                        </div>
                        <span style={{ fontSize: ".7rem", color: "var(--green)", flexShrink: 0 }}>Open →</span>
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          </div>

          {/* ── RIGHT: cards grid ── */}
          <div className="g2">
            {filtered.map((item, ci) => (
              <div
                key={item.id}
                className="card fu"
                style={{
                  padding: "1.5rem",
                  cursor: "pointer",
                  animationDelay: `${ci * .07}s`,
                  display: "flex",
                  flexDirection: "column",
                }}
                onClick={() => {
                  if (item.url) openUrl(item.url, item.title);
                  else if (item.links?.[0]) openUrl(item.links[0].url, item.links[0].label);
                }}
              >
                {/* Top row: tag + date */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
                  <span className={`tag ${TAG_COLORS[item.tag] || "t-blue"}`}>{item.tag}</span>
                  <span style={{ fontSize: ".72rem", color: "var(--text3)" }}>{item.date}</span>
                </div>

                {/* Title */}
                <h3 style={{ fontFamily: "var(--ff)", fontSize: "1.15rem", color: "var(--text)", marginBottom: ".5rem", lineHeight: 1.4 }}>
                  {item.title}
                </h3>

                {/* Description */}
                {item.description && (
                  <p style={{ fontSize: ".83rem", color: "var(--text2)", lineHeight: 1.65, marginBottom: ".85rem" }}>
                    {item.description}
                  </p>
                )}

                {/* Footer */}
                <div style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  paddingTop: ".75rem",
                  borderTop: "1px solid var(--border)",
                  marginTop: "auto",
                }}>
                  <span style={{ fontSize: ".76rem", color: "var(--text3)" }}>📰 {item.source}</span>
                  <span style={{ fontSize: ".72rem", color: "var(--green)" }}>
                    {item.links?.length ? `${item.links.length} links →` : "Read →"}
                  </span>
                </div>
              </div>
            ))}
          </div>

        </div>
      )}

      {/* ── Full-page iframe overlay ── */}
      {activeUrl && (
        <div
          style={{
            position: "fixed", inset: 0, zIndex: 9999,
            background: "var(--modal-overlay)",
            backdropFilter: "blur(6px)",
            display: "flex", flexDirection: "column",
            animation: "fadeIn .2s ease",
          }}
        >
          {/* Top bar */}
          <div style={{
            display: "flex", alignItems: "center", gap: ".75rem",
            padding: ".65rem 1rem",
            background: "var(--bg2)", borderBottom: "1px solid var(--border)",
            flexShrink: 0,
          }}>
            <button
              className="btn btn-o"
              style={{ fontSize: ".78rem", padding: ".35rem .9rem", flexShrink: 0 }}
              onClick={() => { setActiveUrl(null); setActiveTitle(""); }}
            >
              ← Back
            </button>
            <div style={{ flex: 1, overflow: "hidden" }}>
              <div style={{ fontSize: ".88rem", color: "var(--text)", fontFamily: "var(--ff)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                {activeTitle}
              </div>
              <div style={{ fontSize: ".7rem", color: "var(--text3)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                {activeUrl}
              </div>
            </div>
            <a
              href={activeUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="btn btn-p"
              style={{ fontSize: ".78rem", padding: ".35rem .9rem", flexShrink: 0, textDecoration: "none" }}
            >
              Open in new tab ↗
            </a>
          </div>

          {/* iframe */}
          <iframe
            src={activeUrl}
            title={activeTitle || "Article viewer"}
            style={{ flex: 1, border: "none", width: "100%", background: "#fff" }}
            sandbox="allow-scripts allow-same-origin allow-popups allow-forms"
          />
        </div>
      )}
    </div>
  );
}
